export function measureTextPx(str, size = 10, tracking = 0) {
  const table = GLYPHS[size] || GLYPHS[10];
  let w = 0;
  for (const ch of str) {
    const g = table[ch];
    w += (g ? g[0] : size) + tracking;
  }
  return Math.max(0, w - tracking);
}

export function drawTextPx(fb, x, y, str, { size = 10, color = 19, shadow = null, outline = null, scale = 1, tracking = 0, maxChars = Infinity } = {}) {
  const table = GLYPHS[size] || GLYPHS[10];
  let cx = Math.round(x);
  const cy = Math.round(y);
  let idx = 0;
  for (const ch of str) {
    if (idx >= maxChars) break;
    idx++;
    const g = table[ch];
    if (!g) { cx += size * scale + tracking; continue; }
    const [adv, rows] = g;
    if (outline !== null) {
      for (let ry = 0; ry < rows.length; ry++) {
        const bits = rows[ry];
        if (!bits) continue;
        for (let rx = 0; rx < 16; rx++) {
          if ((bits >> rx) & 1) {
            for (let oy = -1; oy <= 1; oy++) {
              for (let ox = -1; ox <= 1; ox++) {
                if (ox === 0 && oy === 0) continue;
                fb.rect(cx + rx * scale + ox, cy + ry * scale + oy, scale, scale, outline);
              }
            }
          }
        }
      }
    } else if (shadow !== null) {
      for (let ry = 0; ry < rows.length; ry++) {
        const bits = rows[ry];
        if (!bits) continue;
        for (let rx = 0; rx < 16; rx++) {
          if ((bits >> rx) & 1) {
            fb.rect(cx + rx * scale + 1, cy + ry * scale + 1, scale, scale, shadow);
          }
        }
      }
    }
    for (let ry = 0; ry < rows.length; ry++) {
      const bits = rows[ry];
      if (!bits) continue;
      for (let rx = 0; rx < 16; rx++) {
        if ((bits >> rx) & 1) {
          fb.rect(cx + rx * scale, cy + ry * scale, scale, scale, color);
        }
      }
    }
    cx += adv * scale + tracking;
  }
  return cx - Math.round(x);
}
